#define NOMINMAX
#include "tokenizer_file.hpp"
#include <cstdio>
int main(){try{std::string hash;tao::text::load_tokenizer("build/formal_tokenizer.bbp",hash);for(auto name:{"train","validation","test"}){std::ifstream in(std::string("build/bpe_pilot_")+name+".bin",std::ios::binary);std::string b((std::istreambuf_iterator<char>(in)),{});if(b.size()<68||b.substr(0,4)!="TLP2"||b.substr(4,64)!=hash)throw std::runtime_error("header");size_t p=68,docs=0,tokens=0,loss=0;while(p<b.size()){if(p+4>b.size())throw std::runtime_error("length");uint32_t n=0;for(int j=0;j<4;++j)n|=uint32_t((unsigned char)b[p++])<<(8*j);if(n<3||n>(b.size()-p)/3)throw std::runtime_error("record");for(uint32_t i=0;i<n;++i){unsigned id=(unsigned char)b[p]|unsigned((unsigned char)b[p+1])<<8,mask=(unsigned char)b[p+2];p+=3;if(id>=16384||id==260||mask>1||(i==0&&(id!=256||mask)))throw std::runtime_error("token");++tokens;loss+=mask;}++docs;}printf("PASS %s docs=%zu tokens=%zu supervised=%zu SHA256=%s\n",name,docs,tokens,loss,tao::text::sha256(b).c_str());}return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
